def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    urgent_opp = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = float(prev['bid'])
                prev_bids.append(b)
                if b >= DAILY_SALARY * 0.8:
                    dangerous_prev.append(b)

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.25))

    capacity = int(supply // WATER_REQ)
    contested = capacity <= len(alive)
    very_tight = capacity <= max(1, len(alive) - 1)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    need_score = 0
    if hp <= 2:
        need_score += 3
    elif hp <= 4:
        need_score += 2
    elif hp <= 6:
        need_score += 1

    if no_water_days >= 2:
        need_score += 3
    elif no_water_days >= 1:
        need_score += 2

    if very_tight:
        need_score += 2
    elif contested:
        need_score += 1

    if urgent_opp >= 2:
        need_score += 1

    if day >= 8:
        need_score += 1

    if need_score <= 1:
        bid = max(8.0, DAILY_SALARY * 0.22)
        if contested:
            bid = max(bid, min(DAILY_SALARY * 0.4, avg_prev * 0.55 if avg_prev > 0 else DAILY_SALARY * 0.32))
    elif need_score <= 3:
        anchor = highest_prev + 1.2 if highest_prev > 0 else DAILY_SALARY * 0.52
        bid = max(DAILY_SALARY * 0.45, anchor)
        if dangerous_prev:
            bid = min(bid, DAILY_SALARY * 0.78)
    elif need_score <= 5:
        anchor = highest_prev + 2.0 if highest_prev > 0 else DAILY_SALARY * 0.72
        bid = max(DAILY_SALARY * 0.68, anchor)
        bid = min(bid, DAILY_SALARY * 0.9)
    else:
        anchor = highest_prev + 3.0 if highest_prev > 0 else DAILY_SALARY * 0.9
        bid = max(DAILY_SALARY * 0.85, anchor)
        bid = min(bid, DAILY_SALARY * 1.05)

    reserve_days = max(0, 10 - int(day))
    soft_cap = budget
    if reserve_days > 0 and need_score <= 3:
        soft_cap = min(soft_cap, max(0.0, budget - reserve_days * DAILY_SALARY * 0.18))

    if hp <= 2 or no_water_days >= 2:
        soft_cap = budget

    final_bid = min(budget, soft_cap, bid)
    if final_bid < 0:
        final_bid = 0.0
    return float(round(final_bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 90
    WATER_REQ = 9
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not prev_bids:
        return float(min(my_status['budget'], DAILY_SALARY * 0.6))

    max_prev = max(prev_bids)

    if my_status['hp'] <= 3:
        return float(min(my_status['budget'], max(max_prev + 2.0, DAILY_SALARY * 0.8)))

    if max_prev >= DAILY_SALARY * 0.9:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    return float(min(my_status['budget'], max_prev + 1.5))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        # If no opponents, spend to ensure survival.
        return min(budget, DAILY_SALARY * 0.6)

    # Read yesterday bids from previous_trace for immediate reaction.
    prev_bids = []
    for oid, o in alive:
        pt = o.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # Aggression threshold inferred from yesterday meta outcome.
    aggressive = highest_prev_bid >= (DAILY_SALARY * 0.5)

    # Estimate how many units of water are likely needed given supply.
    # If supply is tight (near 15), only a few players can secure water.
    tight_supply = supply <= float(WATER_REQ) + 2.0 or supply <= float(MIN_SUPPLY) + 0.5

    # Endgame urgency: if I'm already losing days without water, increase bid.
    urgency = 0.0
    if no_water_days >= 2:
        urgency += 1.0
    if hp <= 2:
        urgency += 2.0
    if hp <= 3:
        urgency += 1.0

    # Base bid policy
    if aggressive:
        # Compete but avoid overpaying unless I'm in danger.
        if urgency >= 2.0 or tight_supply:
            target = min(budget, max(highest_prev_bid * 0.95, DAILY_SALARY * 0.65))
        else:
            target = min(budget, max(highest_prev_bid * 0.55, DAILY_SALARY * 0.45))
    else:
        # If others weren't bidding extremely, conserve budget.
        if urgency >= 2.0 or tight_supply:
            target = min(budget, max(DAILY_SALARY * 0.75, highest_prev_bid + 5.0))
        else:
            target = min(budget, max(DAILY_SALARY * 0.5, highest_prev_bid * 0.6))

    # Ensure we don't bid trivially when supply is tight.
    if tight_supply and target < DAILY_SALARY * 0.35:
        target = min(budget, DAILY_SALARY * 0.45)

    # If budget is very low, bid what we can.
    if budget <= 10.0:
        return max(0.0, min(budget, 10.0))

    return float(max(0.0, min(budget, target)))
